insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Modern','match_the_following','medium','Match List-I (Viceroy) with List-II (Event associated with their tenure):','{"list_1": ["A. Lord Curzon", "B. Lord Ripon", "C. Lord Irwin", "D. Lord Linlithgow"], "list_2": ["1. Partition of Bengal (1905)", "2. Ilbert Bill controversy (1883)", "3. Civil Disobedience Movement / Dandi March (1930)", "4. August Offer (1940)"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "c", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}, {"id": "d", "body": "A-4, B-2, C-1, D-3", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: Lord Curzon -- Partition of Bengal (1905); Lord Ripon -- Ilbert Bill controversy (1883); Lord Irwin -- Civil Disobedience Movement and the Dandi March (1930); Lord Linlithgow -- the August Offer (1940). Each viceroy is associated with a distinct, well-documented event of their tenure.','modern-viceroys-events-match','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapters covering the viceroyalties from Ripon to Linlithgow.','draft'),
('upsc','History','Modern','match_the_following','medium','Match List-I (Revolutionary/Leader) with List-II (Organisation they founded or led):','{"list_1": ["A. Bhagat Singh", "B. Surya Sen", "C. V. D. Savarkar", "D. Lala Hardayal"], "list_2": ["1. Naujawan Bharat Sabha", "2. Led the Chittagong Armoury Raid group", "3. Abhinav Bharat Society", "4. Ghadar Party"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-3, B-2, C-1, D-4", "isCorrect": false}, {"id": "c", "body": "A-1, B-4, C-3, D-2", "isCorrect": false}, {"id": "d", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: Bhagat Singh -- co-founder of the Naujawan Bharat Sabha; Surya Sen -- leader of the group behind the Chittagong Armoury Raid; V. D. Savarkar -- founder of the Abhinav Bharat Society; Lala Hardayal -- a founding figure of the Ghadar Party in the United States.','modern-revolutionaries-organisations-match','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on revolutionary movements.','draft'),
('upsc','History','Modern','match_the_following','medium','Match List-I (Legislation) with List-II (Key provision):','{"list_1": ["A. Indian Councils Act, 1909", "B. Government of India Act, 1919", "C. Government of India Act, 1935", "D. Indian Independence Act, 1947"], "list_2": ["1. Introduced separate electorates for Muslims", "2. Introduced dyarchy in the provinces", "3. Provided for an All India Federation and provincial autonomy", "4. Partitioned British India into India and Pakistan"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "c", "body": "A-1, B-3, C-4, D-2", "isCorrect": false}, {"id": "d", "body": "A-3, B-2, C-1, D-4", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: the 1909 Act (Morley-Minto reforms) introduced separate electorates for Muslims; the 1919 Act (Montagu-Chelmsford reforms) introduced dyarchy in the provinces; the 1935 Act proposed an All India Federation and provincial autonomy; and the 1947 Act partitioned British India into the dominions of India and Pakistan.','modern-constitutional-acts-provisions-match','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on constitutional developments.','draft'),
('upsc','History','Ancient','match_the_following','medium','Match List-I (Dynasty) with List-II (Capital):','{"list_1": ["A. Mauryas", "B. Kushans", "C. Satavahanas", "D. Indo-Greeks (under Menander)"], "list_2": ["1. Pataliputra", "2. Purushapura (Peshawar)", "3. Pratishthana (Paithan)", "4. Sagala (Sialkot)"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}, {"id": "c", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "d", "body": "A-4, B-2, C-3, D-1", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: the Mauryas were centred at Pataliputra; the Kushans (under rulers like Kanishka) at Purushapura, present-day Peshawar; the Satavahanas at Pratishthana (Paithan) in the Deccan; and the Indo-Greeks, including Menander, at Sagala (present-day Sialkot).','ancient-dynasties-capitals-match','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapters on the Mauryas, Kushans, Satavahanas and Indo-Greeks.','draft'),
('upsc','History','Ancient','match_the_following','medium','Match List-I (Text) with List-II (Author):','{"list_1": ["A. Arthashastra", "B. Mudrarakshasa", "C. Indica", "D. Harshacharita"], "list_2": ["1. Kautilya", "2. Vishakhadatta", "3. Megasthenes", "4. Banabhatta"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}, {"id": "c", "body": "A-4, B-2, C-3, D-1", "isCorrect": false}, {"id": "d", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: the Arthashastra is attributed to Kautilya; the Mudrarakshasa, a play about Chandragupta Maurya''s rise, was written by Vishakhadatta; the Indica is the account of the Greek ambassador Megasthenes; and the Harshacharita, a biography of Harshavardhana, was written by his court poet Banabhatta.','ancient-texts-authors-match','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapters on Mauryan and post-Gupta literary sources.','draft'),
('upsc','History','Ancient','match_the_following','medium','Match List-I (Buddhist Council) with List-II (Venue):','{"list_1": ["A. First Buddhist Council", "B. Second Buddhist Council", "C. Third Buddhist Council", "D. Fourth Buddhist Council"], "list_2": ["1. Rajagriha", "2. Vaishali", "3. Pataliputra", "4. Kundalavana (Kashmir)"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "c", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}, {"id": "d", "body": "A-3, B-2, C-1, D-4", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: the First Council was held at Rajagriha, the Second at Vaishali, the Third (under Ashoka) at Pataliputra, and the Fourth (under Kanishka) at Kundalavana in Kashmir.','ancient-buddhist-councils-venues-match','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the spread and councils of Buddhism.','draft'),
('upsc','History','Modern','match_the_following','easy','Match List-I (Leader) with List-II (Newspaper/journal founded by them):','{"list_1": ["A. Bal Gangadhar Tilak", "B. Mahatma Gandhi", "C. Annie Besant", "D. Lala Lajpat Rai"], "list_2": ["1. Kesari", "2. Young India", "3. New India", "4. The Punjabee"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "c", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}, {"id": "d", "body": "A-4, B-2, C-1, D-3", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: Tilak founded Kesari; Gandhi founded Young India; Annie Besant founded New India; and Lala Lajpat Rai founded The Punjabee.','modern-leaders-newspapers-match','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the nationalist press.','draft'),
('upsc','History','Modern','match_the_following','easy','Match List-I (Event) with List-II (Year):','{"list_1": ["A. Formation of the Indian National Congress", "B. Partition of Bengal", "C. Jallianwala Bagh massacre", "D. Quit India Movement"], "list_2": ["1. 1885", "2. 1905", "3. 1919", "4. 1942"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "c", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}, {"id": "d", "body": "A-4, B-2, C-1, D-3", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: the Indian National Congress was formed in 1885, the Partition of Bengal was announced in 1905, the Jallianwala Bagh massacre occurred in 1919, and the Quit India Movement was launched in 1942.','modern-events-years-match','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- general chronology of the freedom struggle.','draft'),
('upsc','History','Ancient','match_the_following','easy','Match List-I (Indus Valley site) with List-II (Present-day location):','{"list_1": ["A. Harappa", "B. Mohenjodaro", "C. Lothal", "D. Kalibangan"], "list_2": ["1. Punjab, Pakistan", "2. Sindh, Pakistan", "3. Gujarat, India", "4. Rajasthan, India"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "c", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}, {"id": "d", "body": "A-3, B-2, C-1, D-4", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: Harappa is in Punjab, Pakistan; Mohenjodaro is in Sindh, Pakistan; Lothal is in Gujarat, India; and Kalibangan is in Rajasthan, India.','ancient-indus-sites-locations-match','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Indus Valley Civilisation and its sites.','draft'),
('upsc','History','Ancient','match_the_following','easy','Match List-I (Ruler) with List-II (Dynasty):','{"list_1": ["A. Chandragupta Maurya", "B. Kanishka", "C. Samudragupta", "D. Gautamiputra Satakarni"], "list_2": ["1. Mauryan dynasty", "2. Kushan dynasty", "3. Gupta dynasty", "4. Satavahana dynasty"], "closing": "Select the correct answer using the codes given below:"}'::jsonb,'[{"id": "a", "body": "A-1, B-2, C-3, D-4", "isCorrect": true}, {"id": "b", "body": "A-2, B-1, C-4, D-3", "isCorrect": false}, {"id": "c", "body": "A-1, B-3, C-2, D-4", "isCorrect": false}, {"id": "d", "body": "A-4, B-2, C-1, D-3", "isCorrect": false}]'::jsonb,2,0.66,'The correct pairing is: Chandragupta Maurya belonged to the Mauryan dynasty, Kanishka to the Kushan dynasty, Samudragupta to the Gupta dynasty, and Gautamiputra Satakarni to the Satavahana dynasty.','ancient-rulers-dynasties-match','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapters on the major ancient Indian dynasties.','draft')
